import openai
from openai import OpenAI

vlm = OpenAI(base_url="http://127.0.0.1:8077/v1", api_key="0")
image_base64 = "data:image/png;base64,"

prompt = "What is the main topic of this image?"


response = vlm.chat.completions.create(
    model="free-vision", messages=[{"role": "user", "content": [{"type": "text", "text": prompt}, {"type": "image_url", "image_url": {"url": image_base64}}]}], stream=False
)

print(response.choices[0].message.content)
